/* GENERATED by gen_hcon_vault.py -- models are generated.
   SAT_PRODUCT_VERSION
   anchor      : HUB_PRODUCT   (kind: hub, origin: map.anchor)
   track       : ratified
   history     : SCD2
   feeders     : 4 emitted of 4 (one per source view AND run)
   runs        : 2 -- opus_health_legacy_v4, opus_health_v2
   payload     : 2 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_PRODUCT_HK
   hashdiff    : SAT_PRODUCT_VERSION_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   BESPOKE LAYER dual_feed_satellite_loader (s6.5): BOTH runs write this satellite.
   The standard satellite layer unions feeders that are disjoint by construction,
   which is the assumption two independent writers break.
   CROSS-RUN RECONCILIATION, DECLARED (carve-out ratified by the mapping counterparty):
   this satellite's anchor is one of the shared objects written by BOTH runs, whose two
   identifier registries are UNRECONCILED. The declared source precedence below is a VALUE
   CHOICE APPLIED TO ROWS THAT MAY REPRESENT TWO UNRECONCILED POPULATIONS -- two writers may
   be describing one entity, or two different parties colliding in one key space, and which
   it is cannot be settled from the map, the model or the SQL.
   WHY THE SCOPE IS EVERY SHARED OBJECT AND NOT A LOW-OVERLAP SUBSET: a hub-level
   business-key-column overlap cannot see the hazard at any threshold. HUB_PARTY's overlap
   of three is IMD_CODE, PART_ID and RM_CODE, all intermediary-side; on the member/customer
   population the overlap is ZERO. The figure is unstable too -- collapsing underscores moves
   it from three to five.
   WHY DECLARE RATHER THAN REFUSE: the choice is made on ASYMMETRY. A DECLARED CONFLICT IS
   RECOVERABLE; A WRONG MERGE IS NOT, AFTER LOAD. That is the justification, not a
   preference.
   The subordinate writer and its registry are NAMED below so the loss is COUNTABLE.
   A load-time assertion in models/assertions/ counts the hash keys actually written by both
   runs. Until it runs, whether the precedence EVER fires is UNKNOWN, not zero.
   INTRA-RUN FAN-IN, 1 attribute/run pair(s) with more than one writer, of
   which 1 are genuinely ARBITRARY. WITHIN one run several source views
   write the same attribute and the map declares NO precedence among them,
   so max() picks arbitrarily -- BUT ONLY AMONG UNDISCRIMINATED WRITERS. A
   writer carrying a resolved `instance` or a declared `redundant_of` is
   SEPARATED, not competing: a nominee's name and a policyholder's name on
   one satellite are DIFFERENT ROWS. BOTH SCOPES are quoted below because a
   bare writer count overstates the arbitrariness -- on PARTY_FULL_NAME it
   overstates it nearly fivefold.
   DECLARED, NOT RESOLVED: choosing among same-run writers would invent an
   authority the map does not provide. NO CROSS-RUN DECISION REACHES THIS.
     VERSION_NUMBER                         opus_health_v2         3 writer(s), of which 3 UNDISCRIMINATED (0 separated by a resolved instance, 0 by redundant_of)  [CROSS-TABLE: check_collapse groups on (table, satellite, attribute, instance, child_key) and CANNOT see this]
   A load-time assertion in models/assertions/ counts the DISTINCT
   values the undiscriminated writers actually supply per key. Until it
   runs, whether they ever disagree is UNKNOWN, not zero.
*/

with feeders as (
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__PRODUCT_CODE))) as HUB_PRODUCT_HK
        , EFFECTIVE_DT as VERSION_EFFECTIVE_DATE
        , cast(null as varchar) as VERSION_NUMBER
        , 'BJAZ_HCS_PLANSI_MAPP' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcs_plansi_mapp') }}
    where (nullif(trim(PRODUCT_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__SCHEME_CODE))) as HUB_PRODUCT_HK
        , cast(null as varchar) as VERSION_EFFECTIVE_DATE
        , SCHEME_VERSION as VERSION_NUMBER
        , 'BJAZ_CTNGY_SCHEME_NR_PARMS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ctngy_scheme_nr_parms') }}
    where (nullif('SCHEME:' || nullif(trim(SCHEME_CODE),''), 'SCHEME:')) is not null
    union all
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__SCHEME_CODE_PLAN_ID))) as HUB_PRODUCT_HK
        , cast(null as varchar) as VERSION_EFFECTIVE_DATE
        , SCHEME_VERSION as VERSION_NUMBER
        , 'BJAZ_CTNGY_SCHEME_PLANS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ctngy_scheme_plans') }}
    where (nullif('SCHEMEPLAN:' || nullif(trim(SCHEME_CODE),'') || '|' || nullif(trim(PLAN_ID),''), 'SCHEMEPLAN:|')) is not null
    union all
    select
        md5(upper('HUB_PRODUCT|' || (HUB_PRODUCT_BK__SCHEME_CODE))) as HUB_PRODUCT_HK
        , cast(null as varchar) as VERSION_EFFECTIVE_DATE
        , SCHEME_VERSION as VERSION_NUMBER
        , 'BJAZ_CTNGY_COVERS_EXT' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_ctngy_covers_ext') }}
    where (nullif('SCHEME:' || nullif(trim(SCHEME_CODE),''), 'SCHEME:')) is not null
),

resolved as (
    select
        HUB_PRODUCT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then VERSION_EFFECTIVE_DATE end) as VERSION_EFFECTIVE_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then VERSION_NUMBER end) as VERSION_NUMBER,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PRODUCT_HK
),

hashed as (
    select
        *,
        case when VERSION_EFFECTIVE_DATE is not null or VERSION_NUMBER is not null
                     then md5(upper(coalesce(cast(VERSION_EFFECTIVE_DATE as varchar), '') || '|' || coalesce(cast(VERSION_NUMBER as varchar), '')))
                end as SAT_PRODUCT_VERSION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PRODUCT_HK is not null
  and SAT_PRODUCT_VERSION_HASHDIFF is not null
